fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    
    // Iterate through all parent nodes
    for i in 0..n / 2 {
        let parent = a[i];
        
        // Check left child
        let left_child_idx = 2 * i + 1;
        if left_child_idx < n && parent > a[left_child_idx] {
            return false;
        }
        
        // Check right child
        let right_child_idx = 2 * i + 2;
        if right_child_idx < n && parent > a[right_child_idx] {
            return false;
        }
    }
    
    true
}